using System;
using System.Drawing;
using System.Drawing.Imaging;
using System.Drawing.Drawing2D;
using System.Runtime.InteropServices;
public static class MotionImage {
  public static Bitmap Load(string p) { using(var s=new Bitmap(p)) { var b=new Bitmap(s.Width,s.Height,PixelFormat.Format32bppArgb);using(var g=Graphics.FromImage(b)){g.CompositingMode=CompositingMode.SourceCopy;g.DrawImageUnscaled(s,0,0);}return b; } }
  public static void Save(Bitmap b,string p,bool rgb=false) { if(rgb) { using(var q=new Bitmap(b.Width,b.Height,PixelFormat.Format24bppRgb)) { using(var g=Graphics.FromImage(q))g.DrawImageUnscaled(b,0,0); q.Save(p,ImageFormat.Png); } } else b.Save(p,ImageFormat.Png); }
  public static Bitmap Resize(Bitmap s,int w,int h) { var b=new Bitmap(w,h,PixelFormat.Format32bppArgb); using(var g=Graphics.FromImage(b)) { g.CompositingMode=CompositingMode.SourceCopy; g.InterpolationMode=InterpolationMode.HighQualityBicubic; g.PixelOffsetMode=PixelOffsetMode.HighQuality; g.DrawImage(s,new Rectangle(0,0,w,h)); } return b; }
  public static void Normalize(string src,string dst,int w,int h,bool rgb) { using(var s=Load(src))using(var b=Resize(s,w,h))Save(b,dst,rgb); }
  public static int[] CanvasTrim(string src,string dst,bool solid) { using(var s=Load(src))using(var b=Resize(s,2304,1296)){if(solid)CleanMatte(b);BitmapData d;var a=Pixels(b,out d);for(int i=0;i<a.Length;i+=4)if(a[i+3]<=8)a[i]=a[i+1]=a[i+2]=a[i+3]=0;Unlock(b,d,a);var z=Bounds(b);if(z[2]==0)throw new Exception("Empty canvas layer: "+src);using(var q=b.Clone(new Rectangle(z[0],z[1],z[2],z[3]),PixelFormat.Format32bppArgb))Save(q,dst);return z;} }
  public static void Fade(string src,string dst,double opacity) { using(var b=Load(src)){BitmapData d;var a=Pixels(b,out d);for(int i=0;i<a.Length;i+=4){a[i+3]=(byte)(a[i+3]*opacity);if(a[i+3]<=8)a[i]=a[i+1]=a[i+2]=a[i+3]=0;}Unlock(b,d,a);Save(b,dst);} }
  public static int[] LightAccents(string dst,string pool,int cut,int x,int y){using(var light=Load(dst))using(var p=Load(pool))using(var b=new Bitmap(2304,1296,PixelFormat.Format32bppArgb)){
    using(var g=Graphics.FromImage(b))using(var ia=new ImageAttributes()){
      g.DrawImageUnscaled(light,x,y);var cm=new ColorMatrix();cm.Matrix33=.10f;ia.SetColorMatrix(cm);
      var target=cut==2?new Rectangle(1390,655,300,60):new Rectangle(1460,860,360,65);
      g.DrawImage(p,target,0,(int)(p.Height*.65),p.Width,(int)(p.Height*.33),GraphicsUnit.Pixel,ia);
      if(cut==4){cm.Matrix33=.28f;ia.SetColorMatrix(cm);g.DrawImage(light,new Rectangle(1674,584,2,165),0,0,light.Width,light.Height,GraphicsUnit.Pixel,ia);}
    }
    BitmapData d;var a=Pixels(b,out d);for(int i=0;i<a.Length;i+=4)if(a[i+3]<=8)a[i]=a[i+1]=a[i+2]=a[i+3]=0;Unlock(b,d,a);var z=Bounds(b);using(var q=b.Clone(new Rectangle(z[0],z[1],z[2],z[3]),PixelFormat.Format32bppArgb))Save(q,dst);return z;
  }}
  public static int[] AlignLight(string src,string lodge,string dst,int x,int y,int w,int h,double opacity,int cut) {
    using(var l=Load(lodge))using(var s0=Load(src))using(var s=Resize(s0,l.Width,l.Height))using(var b=new Bitmap(l.Width,l.Height,PixelFormat.Format32bppArgb)) {
      // Match generated light panes to the actual lodge glass; no roof/wall pixels enter the light layer.
      int[][] rects=cut==2?new[]{new[]{188,647,96,151,211,691,70,120},new[]{950,565,116,175,967,637,76,124},new[]{1255,648,100,156,1271,728,69,104}}:new[]{new[]{326,474,89,146,374,497,65,100},new[]{938,418,111,194,978,446,80,136},new[]{1203,514,103,182,1219,532,74,121}};
      using(var g=Graphics.FromImage(b)){g.InterpolationMode=InterpolationMode.HighQualityBicubic;foreach(var r in rects)g.DrawImage(s,new Rectangle(r[4],r[5],r[6],r[7]),new Rectangle(r[0],r[1],r[2],r[3]),GraphicsUnit.Pixel);}
      CleanMatte(l);var z=Bounds(l);using(var c=b.Clone(new Rectangle(z[0],z[1],z[2],z[3]),PixelFormat.Format32bppArgb))using(var scaled=Resize(c,w,h)){
        BitmapData d;var a=Pixels(scaled,out d);for(int i=0;i<a.Length;i+=4){a[i+3]=(byte)(a[i+3]*opacity);if(a[i+3]<=8)a[i]=a[i+1]=a[i+2]=a[i+3]=0;}Unlock(scaled,d,a);var q=Bounds(scaled);using(var trimmed=scaled.Clone(new Rectangle(q[0],q[1],q[2],q[3]),PixelFormat.Format32bppArgb))Save(trimmed,dst);return new[]{x+q[0],y+q[1],q[2],q[3]};
      }
    }
  }
  static byte[] Pixels(Bitmap b,out BitmapData d) { d=b.LockBits(new Rectangle(0,0,b.Width,b.Height),ImageLockMode.ReadWrite,PixelFormat.Format32bppArgb); var a=new byte[d.Stride*b.Height]; Marshal.Copy(d.Scan0,a,0,a.Length); return a; }
  static void Unlock(Bitmap b,BitmapData d,byte[] a) { Marshal.Copy(a,0,d.Scan0,a.Length);b.UnlockBits(d); }
  static void CleanMatte(Bitmap b){BitmapData d;var a=Pixels(b,out d);var original=(byte[])a.Clone();for(int y=0;y<b.Height;y++)for(int x=0;x<b.Width;x++){int i=y*d.Stride+x*4;if(original[i+3]>=240)continue;bool near=false;for(int dy=-2;dy<=2&&!near;dy++)for(int dx=-2;dx<=2;dx++){int xx=x+dx,yy=y+dy;if(xx>=0&&yy>=0&&xx<b.Width&&yy<b.Height&&original[yy*d.Stride+xx*4+3]>=240){near=true;break;}}if(!near)a[i]=a[i+1]=a[i+2]=a[i+3]=0;}Unlock(b,d,a);}
  public static int[] Bounds(Bitmap b) { BitmapData d;var a=Pixels(b,out d);int l=b.Width,t=b.Height,r=-1,bt=-1;for(int y=0;y<b.Height;y++)for(int x=0;x<b.Width;x++)if(a[y*d.Stride+x*4+3]>8){l=Math.Min(l,x);r=Math.Max(r,x);t=Math.Min(t,y);bt=Math.Max(bt,y);}Unlock(b,d,a);return r<0?new[]{0,0,0,0}:new[]{l,t,r-l+1,bt-t+1}; }
  public static int[] Prepare(string src,string dst,int x,int y,int w,int h,bool solid=false) { using(var s=Load(src)) { if(solid)CleanMatte(s);var bb=Bounds(s);if(bb[2]==0)throw new Exception("Empty generated alpha: "+src);using(var c=s.Clone(new Rectangle(bb[0],bb[1],bb[2],bb[3]),PixelFormat.Format32bppArgb))using(var b=Resize(c,w,h)) { BitmapData d;var a=Pixels(b,out d); for(int j=0;j<a.Length;j+=4)if(a[j+3]<=8){a[j]=a[j+1]=a[j+2]=a[j+3]=0;} Unlock(b,d,a);var z=Bounds(b);if(w==2304){z[0]=0;z[2]=2304;}using(var q=b.Clone(new Rectangle(z[0],z[1],z[2],z[3]),PixelFormat.Format32bppArgb))Save(q,dst); return new[]{x+z[0],y+z[1],z[2],z[3]}; } } }
  public static int[] Parts(string src,string dst,int[] rects){using(var s=Load(src))using(var b=new Bitmap(2304,1296,PixelFormat.Format32bppArgb)){for(int i=0;i<rects.Length;i+=8){using(var c=s.Clone(new Rectangle(rects[i],rects[i+1],rects[i+2],rects[i+3]),PixelFormat.Format32bppArgb))using(var r=Resize(c,rects[i+6],rects[i+7]))using(var g=Graphics.FromImage(b))g.DrawImageUnscaled(r,rects[i+4],rects[i+5]);}var z=Bounds(b);using(var q=b.Clone(new Rectangle(z[0],z[1],z[2],z[3]),PixelFormat.Format32bppArgb))Save(q,dst);return z;}}
  public static void Composite(string[] paths,int[] positions,bool[] adds,string dst,bool screen) { using(var b=new Bitmap(2304,1296,PixelFormat.Format32bppArgb)) { for(int i=0;i<paths.Length;i++)using(var s=Load(paths[i])) { int x=positions[i*2],y=positions[i*2+1]; if(!adds[i]) {using(var g=Graphics.FromImage(b))g.DrawImageUnscaled(s,x,y);}else {BitmapData bd,sd;var ba=Pixels(b,out bd);var sa=Pixels(s,out sd);for(int yy=0;yy<s.Height;yy++)for(int xx=0;xx<s.Width;xx++){int dx=x+xx,dy=y+yy;if(dx<0||dy<0||dx>=b.Width||dy>=b.Height)continue;int k=yy*sd.Stride+xx*4,j=dy*bd.Stride+dx*4;float al=sa[k+3]/255f;for(int z=0;z<3;z++)ba[j+z]=(byte)Math.Min(255,ba[j+z]+sa[k+z]*al);}Unlock(s,sd,sa);Unlock(b,bd,ba);} } if(screen)using(var c=b.Clone(new Rectangle(192,108,1920,1080),PixelFormat.Format32bppArgb))Save(c,dst,true);else Save(b,dst,true); } }
  public static void DuskGrade(string src,string palette,string dst) { using(var b=Load(src))using(var p0=Load(palette))using(var p=Resize(p0,b.Width,b.Height)){BitmapData d,pd;var a=Pixels(b,out d);var pa=Pixels(p,out pd);for(int y=0;y<b.Height;y++){var av=new double[3];var pv=new double[3];int lo=Math.Max(0,y-12),hi=Math.Min(b.Height-1,y+12);for(int yy=lo;yy<=hi;yy++)for(int x=0;x<b.Width;x+=8)for(int c=0;c<3;c++){av[c]+=a[yy*d.Stride+x*4+c];pv[c]+=pa[yy*pd.Stride+x*4+c];}double count=(hi-lo+1)*((b.Width+7)/8);for(int x=0;x<b.Width;x++){int i=y*d.Stride+x*4;for(int c=0;c<3;c++){double delta=(pv[c]-av[c])/count; a[i+c]=(byte)Math.Max(0,Math.Min(255,a[i+c]+delta*.8));}}}Unlock(p,pd,pa);Unlock(b,d,a);Save(b,dst,true);} }
  public static void Frame(string src,string dst){using(var s=Load(src))using(var b=Resize(s,1920,1080)){BitmapData d;var a=Pixels(b,out d);for(int y=0;y<1080;y++)for(int x=0;x<1920;x++){int k=y*d.Stride+x*4;if(x>=70&&x<1850&&y>=70&&y<1010)a[k]=a[k+1]=a[k+2]=a[k+3]=0;}Unlock(b,d,a);Save(b,dst);} }
  public static string Info(string path){using(var b=Load(path)){var z=Bounds(b);BitmapData d;var a=Pixels(b,out d);long zero=0,semi=0,solid=0;for(int i=3;i<a.Length;i+=4){if(a[i]==0)zero++;else if(a[i]==255)solid++;else semi++;}Unlock(b,d,a);return String.Join(",",new long[]{b.Width,b.Height,z[0],z[1],z[2],z[3],zero,semi,solid});}}
  public static long CropDifference(string master,string preview){using(var m=Load(master))using(var p=Load(preview)){long count=0;for(int y=0;y<p.Height;y++)for(int x=0;x<p.Width;x++)if(m.GetPixel(x+192,y+108).ToArgb()!=p.GetPixel(x,y).ToArgb())count++;return count;}}
}
